// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RevenueEvidence) predicate.RevenueEvidence {
	return predicate.RevenueEvidence(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RevenueEvidence) predicate.RevenueEvidence {
	return predicate.RevenueEvidence(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RevenueEvidence) predicate.RevenueEvidence {
	return predicate.RevenueEvidence(sql.NotPredicates(p))
}
